"""Compact summary and lossless compressed metadata for retention."""
from pathlib import Path
import gzip,hashlib,json
OUT=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
rows=[json.loads(p.read_text(encoding='utf-8')) for p in sorted(OUT.glob('*.metadata.json'))]
assert len(rows)==7
def coords(v):return sum(x/d for x,d in zip(v,[1,60,3600,3600000000])) if v else None
sources=[]
for d in rows:
    p=OUT/(d['source_name']+'.metadata.json');z=p.with_suffix(p.suffix+'.gz')
    z.write_bytes(gzip.compress(p.read_bytes(),compresslevel=9,mtime=0))
    identities=d['project_identity_approval_and_reference_records']
    sites=[{'step_id':r['id'],'name':r['Name'],'raw_latitude':r['RefLatitude'],'raw_longitude':r['RefLongitude'],'latitude_decimal':coords(r['RefLatitude']),'longitude_decimal':coords(r['RefLongitude'])} for r in identities if r['type']=='IfcSite']
    properties={name:{'instances':ps['instances'],'property_names':list(ps['properties'])} for name,ps in d['property_set_summary'].items()}
    sources.append({'source_name':d['source_name'],'source_sha256':d['source_sha256_before'],'source_unchanged':d['source_unchanged'],'metadata_json_sha256':sha(p),'compressed_metadata':z.name,'compressed_sha256':sha(z),'sites':sites,'addresses':[r for r in identities if r['type']=='IfcPostalAddress'],'projects':[r for r in identities if r['type']=='IfcProject'],'classifications':[r for r in identities if r['type']=='IfcClassification'],'counts':d['including_subtypes_counts'],'assignment_coverage':d['assignment_coverage'],'property_set_summary':properties,'material_names':[m['Name'] for m in d['materials']]})
all_segment_coverage={k:sum(d['assignment_coverage']['IfcFlowSegment'][k] for d in rows) for k in rows[0]['assignment_coverage']['IfcFlowSegment']}
fire_props=[r for d in rows for r in d['semantic_keyword_hits'] if r.get('Name')=='FireRating']
result={'status':'CODE_COMPLIANCE_NOT_ESTABLISHED_BY_AVAILABLE_MODEL_METADATA','sources':sources,'total_IFC_products':sum(d['including_subtypes_counts']['IfcProduct'] for d in rows),'all_flow_segments_assignment_coverage':all_segment_coverage,'zero_across_all_sources':[t for t in rows[0]['including_subtypes_counts'] if all(d['including_subtypes_counts'][t]==0 for d in rows)],'fire_rating_property_observation':{'property_count':len(fire_props),'distinct_values':sorted({r['NominalValue']['value'] for r in fire_props}),'scope':'These are unspecific curtain-wall labels, not authenticated installed assembly ratings, required compartment ratings or proof of listed systems.'},'conclusions':[{'id':'jurisdiction','status':'UNRESOLVED','observation':'All street addresses are Enter address here. Architecture coordinates, mechanical coordinates and other files coordinates disagree. Boston/MA labels and numerical strings in region/country fields are not an authenticated address or governing-code selection.'},{'id':'design_loads','status':'UNRESOLVED','observation':'No structural analytical model/load entities, load groups or structural result groups are embedded. Material names include steel 345 MPa and concrete 35 MPa, but do not establish applied loads, calculation adequacy, design strength or construction approval.'},{'id':'mep_duties','status':'UNRESOLVED','observation':'The available MEP property names are Reference, IsExternal, Manufacturer, AboveGround and NumberOfStoreys. No separately named flow/pressure/duty/circuit/hydraulic criterion properties are present. Textual Reference/type labels may contain numerical descriptions; this audit does not promote those labels to authenticated engineering criteria. All 19,352 segments lack direct and type-associated IfcPropertySet/IfcRelAssociatesMaterial assignments.'},{'id':'room_requirements','status':'UNRESOLVED','observation':'There are zero IfcSpace or IfcZone objects across all seven files, so no explicit room-use schedules, pressure relationships or room ventilation targets are recoverable from those objects.'},{'id':'approvals','status':'UNRESOLVED','observation':'No IfcApproval, IfcRelAssociatesApproval, IfcDocumentInformation or IfcDocumentReference records are embedded in any of the seven IFC4 files. Classification records identify Uniformat 1998, which is not a building-code adoption or approval record.'}],'counterpart_property_recovery':'ifc2x3-property-recovery.json','counterpart_recovery_sha256':sha(OUT/'ifc2x3-property-recovery.json'),'limitations':['No missing field is treated as a violation.','No system receives a code pass from this metadata audit.','This does not validate geometry, hydraulic/electrical/structural behavior, installation, supports, required clearances or current code adoption.','Some equipment is represented by generic proxies; zero typed equipment classes does not prove the equipment is absent.','The zero segment-assignment result is limited to direct and associated-type relationships, not all parent/system metadata, type names, text labels, geometry dimensions or indirect associations.'],'script_sha256':sha(Path(__file__))}
(OUT/'summary.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
print(json.dumps({'source_count':len(rows),'all_flow_segments_assignment_coverage':all_segment_coverage,'fire_rating_count':len(fire_props),'summary_sha256':sha(OUT/'summary.json')},indent=2))
